package com.digitalhealth.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="appointments",indexes=@Index(name="idx_appointment_worker_date",columnList="worker_id,appointment_at"),uniqueConstraints=@UniqueConstraint(columnNames={"worker_id","provider","appointment_at"})) public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="worker_id",nullable=false) private Worker worker; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="center_id") private HealthcareCenter center; @Column(nullable=false) private String provider; @Column(name="appointment_at",nullable=false) private LocalDateTime appointmentAt; @Column(nullable=false) private String status="PENDING"; @Column(columnDefinition="TEXT") private String reason; @Column(columnDefinition="TEXT") private String notes; public Long getId(){return id;} public Worker getWorker(){return worker;} public void setWorker(Worker x){worker=x;} public HealthcareCenter getCenter(){return center;} public void setCenter(HealthcareCenter x){center=x;} public String getProvider(){return provider;} public void setProvider(String x){provider=x;} public LocalDateTime getAppointmentAt(){return appointmentAt;} public void setAppointmentAt(LocalDateTime x){appointmentAt=x;} public String getStatus(){return status;} public void setStatus(String x){status=x;} public String getReason(){return reason;} public void setReason(String x){reason=x;} public String getNotes(){return notes;} public void setNotes(String x){notes=x;} }
